    /// @notice Address of the immutable contract which stores the implementation address for a beacon.
    function getUpgradeableBeaconForFactory() external view returns (address);

    /// @notice Address of the implementation which will be used for the deployed BeaconProxy contracts.
    function getBeaconProxyImplementationForFactory() external view returns (address);
}

/// @notice Interface for the contract which manages the upgrade of beacon factory implementations.
/// @dev This architecture is built with security in mind. The UpgradeableBeacon and BeaconFactoryAdmin are
///  intended on being immutable
interface IBeaconFactoryAdmin {
    /// @notice Address which can perform BeaconProxy upgrades to the UpgradeableBeaconForFactory.
    function secureTimelockController() external view returns (address);

    /// @notice Set the beacon implementation for a given factory
    /// @dev WARN this function affects the contract code for all contracts created by the factory
    function upgradeBeaconFactoryImplementation(
        IBeaconFactory _beaconFactory,
        address _newBeaconImplementation
    ) external;

    /// @notice Upgrades the implementation of an upgradeable beacon
    /// @param _upgradeableBeacon The address of the upgradeable beacon
    /// @param _newBeaconImplementation The address of the new beacon implementation
    function upgradeBeaconImplementation(
        IUpgradeableBeacon _upgradeableBeacon,
        address _newBeaconImplementation
    ) external;

    /// @notice Deploys an UpgradeableBeaconForFactory for the factory.
    function deployUpgradeableBeaconForFactory(
        string memory _beaconFactoryName,
        IBeaconFactory _beaconFactory,
        address _startingBeaconImplementation
    ) external returns (IUpgradeableBeacon);

    /// @notice Returns true if the caller is the admin for the upgradeable beacon.
    function isAdminForUpgradeableBeacon(address _upgradeableBeacon) external view returns (bool);
}
"
    },
    "contracts/factories/GaugeFactoryV2.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.13;

import {BeaconProxy} from "@openzeppelin/contracts/proxy/beacon/BeaconProxy.sol";
import {IUpgradeableBeacon, IBeaconFactory, IBeaconFactoryAdmin} from "./beacon-factory/IBeaconFactory.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {Ownable2StepUpgradeable} from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import {IGaugeFactoryV2} from "./interfaces/IGaugeFactoryV2.sol";
import {IVersionable} from "../interfaces/IVersionable.sol";
import {IPermissionsRegistry} from '../interfaces/IPermissionsRegistry.sol';
import {IGaugeV2} from '../interfaces/IGaugeV2.sol';
import {IMultiTokenPool} from '../interfaces/IMultiTokenPool.sol';
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title GaugeFactoryV2
 * @notice Beacon Factory contract to create GaugeV2 contracts.
 * @dev 
 *  - WARN This factory acts an upgradeable beacon which has the ability to upgrade the implementation of all deployed contracts.
 *  - beaconFactoryAdmin MUST be a BeaconFactoryAdmin contract with the secureTimelockController set to
 *    a TimelockController with at least a 72 hour delay.
 */
contract GaugeFactoryV2 is IGaugeFactoryV2, IBeaconFactory, IVersionable, Ownable2StepUpgradeable {

    /// -----------------------------------------------------------------------
    /// Constants
    /// -----------------------------------------------------------------------
    
    /**
     * @dev changelog
     * - 2.1.0 Change the factory to a Beacon Proxy Factory
     * - 2.2.0 Add beaconFactoryAdmin protection (__gap reduced to [48])
     * - 2.3.0 Add UpgradeableBeaconForFactory to provide immutable access to the beacon implementation (__gap increased to [49])
     *   - WARN Cannot upgrade from 2.2.0 to 2.3.0 without a new factory (storage collision)
     * - 2.4.0 Add MultiTokenPool integration with secure pool revocation
     */
    string public constant override VERSION = "2.4.0";

    /// -----------------------------------------------------------------------
    /// Storage Variables
    /// -----------------------------------------------------------------------

    address public last_gauge;
    address public permissionsRegistry;

    address[] internal __gauges;

    /// @notice Immutable beacon contract for more secure access
    IUpgradeableBeacon private __upgradeableBeaconForFactory;

    /// @notice Central token pool for cross-chain token storage (can be address(0) to disable)
    /// @dev CRITICAL: If this changes, existing funds must still be withdrawable by users
    address public centralTokenPool;

    /// @dev Uses initialize instead of constructor
    uint256[48] private __gap;

    /// -----------------------------------------------------------------------
    /// Events
    /// -----------------------------------------------------------------------


    event SetRegistry(address newRegistry);
    event CentralTokenPoolSet(address indexed prevPool, address indexed pool);

    /// -----------------------------------------------------------------------
    /// Constructor
    /// -----------------------------------------------------------------------

    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _permissionRegistry, 
        address _implementation, 
        address _beaconFactoryAdmin
    ) initializer  public {
        __Ownable_init();   //after deploy ownership to multisig
        permissionsRegistry = _permissionRegistry;

        require(isValidateBeaconImplementation(_implementation), 'invalid implementation');
        __upgradeableBeaconForFactory = IBeaconFactoryAdmin(_beaconFactoryAdmin).deployUpgradeableBeaconForFactory(
            "GaugeFactoryV2",      // _beaconFactoryName
            IBeaconFactory(this),  // _beaconFactory
            _implementation       // _startingBeaconImplementation
        );
    }

    /// -----------------------------------------------------------------------
    /// External functions
    /// -----------------------------------------------------------------------
    
    function setRegistry(address _registry) external {
        require(owner() == msg.sender, 'not owner');
        permissionsRegistry = _registry;
        emit SetRegistry(permissionsRegistry);
    }

    function gauges() external view returns(address[] memory) {
        return __gauges;
    }

    function length() external view returns(uint) {
        return __gauges.length;
    }

    /// @notice Helper for verification
    function getGaugeV2InitData(
        address _rewardToken,
        address _ve,
        address _token,
        address _distribution,
        bool _isPair
    ) public pure returns (bytes memory) {
        return abi.encodeWithSelector(IGaugeV2.initialize.selector, _rewardToken, _ve, _token, _distribution, _isPair);
    }

    /// @notice Creates a new GaugeV2 Beacon Proxy with the given parameters
    /// @notice internal_bribe and external_bribe are unused parameters for backwards compatibility with VoterV5
    function createGaugeV2(
        address _rewardToken,
        address _ve,
        address _token,
        address _distribution,
        address /*_internal_bribe*/,
        address /*_external_bribe*/,
        bool _isPair
    ) external returns (address) {
        bytes memory implementationData = getGaugeV2InitData(_rewardToken, _ve, _token, _distribution, _isPair);
        
        BeaconProxy newGauge = new BeaconProxy(
            address(__upgradeableBeaconForFactory),
            implementationData
        );
        emit BeaconProxyData(address(newGauge), implementationData);

        last_gauge = address(newGauge);
        __gauges.push(last_gauge);
        return last_gauge;
    }

    /// -----------------------------------------------------------------------
    /// Beacon Factory functions
    /// -----------------------------------------------------------------------
    
    /// @notice Perform a check to see if a given implementation adheres to a valid interface for the factory
    function isValidateBeaconImplementation(address _newImplementation) public override(IBeaconFactory) view returns (bool) {
        return IGaugeV2(_newImplementation).supportsInterface(type(IGaugeV2).interfaceId);
    }

    /// @notice Address of the immutable contract which stores the implementation address for a beacon.
    function getUpgradeableBeaconForFactory() external override(IBeaconFactory) view returns (address) {
        return address(__upgradeableBeaconForFactory);
    }
    
    /// @notice Address of the implementation which will be used for the deployed BeaconProxy contracts.
    function getBeaconProxyImplementationForFactory() external override(IBeaconFactory) view returns (address) {
        return __upgradeableBeaconForFactory.implementation();
    }

    /// -----------------------------------------------------------------------
    /// Modifiers
    /// -----------------------------------------------------------------------

    modifier onlyAllowed() {
        require(owner() == msg.sender || IPermissionsRegistry(permissionsRegistry).hasRole("GAUGE_ADMIN",msg.sender), 'ERR: GAUGE_ADMIN');
        _;
    }

    modifier EmergencyCouncil() {
        require(msg.sender == IPermissionsRegistry(permissionsRegistry).emergencyCouncil(), 'ERR: EMERGENCY_COUNCIL');
        _;
    }

    /// -----------------------------------------------------------------------
    /// EmergencyCouncil functions
    /// -----------------------------------------------------------------------

    function activateEmergencyMode( address[] memory _gauges) external EmergencyCouncil {
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGaugeV2(_gauges[i]).activateEmergencyMode();
        }
    }

    function stopEmergencyMode( address[] memory _gauges) external EmergencyCouncil {
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGaugeV2(_gauges[i]).stopEmergencyMode();
        }
    }

    /// -----------------------------------------------------------------------
    /// Admin functions
    /// -----------------------------------------------------------------------

    function setPermissionsRegistry(address _registry) external onlyAllowed {
        require(_registry != address(0));
        permissionsRegistry = _registry;
    }

    function setGaugeRewarder( address[] memory _gauges, address[] memory _rewarder) external onlyAllowed {
        require(_gauges.length == _rewarder.length);
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGaugeV2(_gauges[i]).setGaugeRewarder(_rewarder[i]);
        }
    }

    function setDistribution(address[] memory _gauges,  address distro) external onlyAllowed {
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGaugeV2(_gauges[i]).setDistribution(distro);
        }
    }

    function addRewardToken(address[] memory _gauges,  address rewardToken) external onlyAllowed {
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGaugeV2(_gauges[i]).addRewardToken(rewardToken);
        }
    }

    function removeRewardToken(address[] memory _gauges,  address rewardToken) external onlyAllowed {
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGaugeV2(_gauges[i]).removeRewardToken(rewardToken);
        }
    }

    function updateRewardToken(address[] memory _gauges) external onlyAllowed {
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGaugeV2(_gauges[i]).updateRewardToken();
        }
    }

    function sweepTokens(address[] memory _gauges, IERC20[][] memory tokens, uint256[][] memory amounts, address to) public onlyAllowed {
        uint i = 0;
        for ( i ; i < _gauges.length; i++) {
            IGaugeV2(_gauges[i]).sweepTokens(tokens[i], amounts[i], to);
        }
    }

    /// -----------------------------------------------------------------------
    /// MultiTokenPool Integration
    /// -----------------------------------------------------------------------

    /// @notice Sets the central token pool address
    /// @dev Can be set to address(0) to disable central pooling
    function setCentralTokenPool(address _pool) external onlyAllowed {
        if (_pool != address(0)) {
            require(
                IMultiTokenPool(_pool).supportsInterface(type(IMultiTokenPool).interfaceId),
                "Invalid pool interface"
            );
        }
        emit CentralTokenPoolSet(centralTokenPool, _pool);
        centralTokenPool = _pool;
    }
}
"
    },
    "contracts/factories/interfaces/IGaugeFactoryV2.sol": {
      "content": "// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.13;

/// @dev Base interface for the GaugeFactoryV2
interface IGaugeFactoryV2_Base {
    /// @notice Creates a new gauge with the given parameters.
    /// @dev Bribes have been extracted and are now being pulled from the VoterV5. The params have been left for backwards compatibility for V2 gauges.
    function createGaugeV2(
        address _rewardToken,
        address _ve,
        address _token,
        address _distribution,
        /// @dev unused parameter for backwards compatibility
        address /*_internal_bribe*/,
        /// @dev unused parameter for backwards compatibility
        address /*_external_bribe*/,
        bool _isPair
    ) external returns (address);

    function activateEmergencyMode(address[] memory _gauges) external;

    function gauges() external view returns (address[] memory);

    function last_gauge() external view returns (address);

    function length() external view returns (uint256);

    function permissionsRegistry() external view returns (address);

    function setDistribution(address[] memory _gauges, address distro) external;

    function setGaugeRewarder(address[] memory _gauges, address[] memory _rewarder) external;

    function setPermissionsRegistry(address _registry) external;

    function stopEmergencyMode(address[] memory _gauges) external;
    
    /// -----------------------------------------------------------------------
    /// MultiTokenPool Integration
    /// -----------------------------------------------------------------------
    
    /// @notice Gets the current central token pool address (can be address(0) to disable)
    /// @dev CRITICAL: Even if this changes, users must always be able to withdraw their funds
    function centralTokenPool() external view returns (address);
    
    /// @notice Sets the central token pool address
    /// @dev Can be set to address(0) to disable central pooling
    ///      CRITICAL: This change does NOT affect existing funds - users can always withdraw
    function setCentralTokenPool(address _pool) external;
}

/// @dev This interface is used to manage gauges which use UniV2 like LP tokens found in this protocol.
interface IGaugeFactoryV2 is IGaugeFactoryV2_Base {
    function initialize(address _permissionRegistry, address _gaugeBeacon, address _beaconFactoryAdmin) external;
}

/// @dev This interface is used to manage gauges which use GAMMA ALM fungible LP tokens for Concentrated Liquidity on Algebra.
interface IGaugeFactoryV2_Gamma is IGaugeFactoryV2_Base {
    
    function initialize(
        address _permissionsRegistry,
        address _gammaFeeRecipient,
        address _pairFactoryClassic,
        address _feeVaultImplementation,
        address _gaugeImplementation,
        address _beaconFactoryAdmin,
        address _wrappedNativeToken
    ) external;

    function gammaFeeRecipient() external view returns (address);

    function last_feeVault() external view returns (address);

    function setGammaDefaultFeeRecipient(address _rec) external;

    function setGaugeFeeVault(address[] memory _gauges, address _vault) external;
}
"
